<?php
declare(strict_types=1);
// Maps the API's record shape onto the proposal's relational tables.
function mysqlStore(callable $fn,bool $write):array{
$p=new PDO(getenv('KUSINA_DSN'),getenv('KUSINA_DB_USER')?:'root',getenv('KUSINA_DB_PASSWORD')?:'',[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_EMULATE_PREPARES=>false]);
$p->beginTransaction();try{$p->query('SELECT id FROM repository_lock WHERE id=1 FOR UPDATE')->fetch();
$rows=fn($q)=>$p->query($q)->fetchAll(PDO::FETCH_ASSOC);$roles=['Customer'=>1,'Staff'=>2,'Admin'=>3];$cats=['Soups'=>1,'Grilled Dishes'=>2,'Main Dishes'=>3,'Noodles'=>4,'Rice, Desserts & Drinks'=>5];
$maps=['users'=>['user_id'=>'id','full_name'=>'name','email'=>'email','phone'=>'phone','password_hash'=>'password_hash','status'=>'active','role_id'=>'role'], 'menu'=>['item_id'=>'id','category_id'=>'category','name'=>'name','description'=>'description','price'=>'price','image_url'=>'image','tag'=>'tag','serving_size'=>'serving','dietary_notes'=>'dietary','is_available'=>'available'], 'orders'=>['order_id'=>'id','user_id'=>'user_id','reference'=>'ref','customer_name'=>'name','email'=>'email','phone'=>'phone','order_type'=>'type','status'=>'status','special_instructions'=>'notes','subtotal'=>'subtotal','delivery_fee'=>'fee','total_amount'=>'total','created_at'=>'created_at'], 'reservations'=>['reservation_id'=>'id','user_id'=>'user_id','reference'=>'ref','customer_name'=>'name','email'=>'email','phone'=>'phone','date'=>'date','time'=>'time','guest_count'=>'guests','occasion'=>'occasion','seating_preference'=>'seating','special_requests'=>'notes','pre_order_notes'=>'preorder','large_group'=>'large_group','status'=>'status','created_at'=>'created_at'], 'inquiries'=>['inquiry_id'=>'id','user_id'=>'user_id','reference'=>'ref','customer_name'=>'name','email'=>'email','phone'=>'phone','event_date'=>'date','event_type'=>'event','guest_count'=>'guests','venue'=>'venue','package'=>'package','notes'=>'notes','status'=>'status','created_at'=>'created_at']];
$tables=['users'=>'users','menu'=>'menu_items','orders'=>'orders','reservations'=>'reservations','inquiries'=>'catering_inquiries'];$items=[];foreach($rows('SELECT * FROM order_items ORDER BY order_item_id') as $r)$items[$r['order_id']][]=['id'=>(int)$r['item_id'],'name'=>$r['dish_name'],'qty'=>(int)$r['quantity'],'price'=>(float)$r['unit_price']];$payments=[];foreach($rows('SELECT * FROM payments') as $r)$payments[$r['order_id']]=$r;
$s=[];foreach($maps as $k=>$map){$s[$k]=[];foreach($rows('SELECT * FROM `'.$tables[$k].'` ORDER BY `'.array_key_first($map).'`') as $r){$x=[];foreach($map as $col=>$key){$v=$r[$col];$x[$key]=match($key){'id','guests'=>(int)$v,'user_id'=>$v===null?null:(int)$v,'price','subtotal','fee','total'=>(float)$v,'active','available','large_group'=>(bool)$v,'role'=>array_search((int)$v,$roles,true),'category'=>array_search((int)$v,$cats,true),'preorder'=>json_decode($v,true,512,JSON_THROW_ON_ERROR),'time'=>substr($v,0,5),default=>$v};}if($k==='orders'){$pay=$payments[$x['id']];$x+=['date'=>substr($r['schedule'],0,10),'time'=>substr($r['schedule'],11,5),'items'=>$items[$x['id']]??[],'payment'=>$pay['method'],'payment_status'=>$pay['status']]+json_decode($r['delivery_address'],true,512,JSON_THROW_ON_ERROR);}$s[$k][]=$x;}}
$new=!$s['users']&&!$s['menu'];if($new)$s=seedState();$old=$new?[]:$s;$result=$fn($s);
if($write||$new){$up=function($table,$data,$keys)use($p){$q=fn($v)=>'`'.$v.'`';$cols=array_keys($data);$sql='INSERT INTO '.$q($table).' ('.implode(',',array_map($q,$cols)).') VALUES ('.implode(',',array_fill(0,count($cols),'?')).') ON DUPLICATE KEY UPDATE '.implode(',',array_map(fn($c)=>$q($c).'=VALUES('.$q($c).')',array_diff($cols,$keys)));$p->prepare($sql)->execute(array_values($data));};
foreach($maps as $k=>$map){$prior=array_column($old[$k]??[],null,'id');foreach($s[$k] as $x){if(isset($prior[$x['id']])&&$prior[$x['id']]===$x)continue;$r=[];foreach($map as $col=>$key){$v=$x[$key];$r[$col]=match($key){'role'=>$roles[$v],'category'=>$cats[$v],'active','available','large_group'=>(int)$v,'preorder'=>json_encode($v,JSON_THROW_ON_ERROR),'time'=>$v.':00',default=>$v};}if($k==='orders'){$r['delivery_address']=json_encode(array_intersect_key($x,array_flip(['street','barangay','city','landmark'])),JSON_THROW_ON_ERROR);$r['schedule']=$x['date'].' '.$x['time'].':00';}$up($tables[$k],$r,[array_key_first($map)]);if($k==='orders'){foreach($x['items'] as $i)$up('order_items',['order_id'=>$x['id'],'item_id'=>$i['id'],'dish_name'=>$i['name'],'quantity'=>$i['qty'],'unit_price'=>$i['price']],['order_id','item_id']);$up('payments',['payment_id'=>$x['id'],'order_id'=>$x['id'],'method'=>$x['payment'],'status'=>$x['payment_status'],'amount'=>$x['total'],'paid_at'=>$x['payment_status']==='Paid'?($payments[$x['id']]['paid_at']??date('Y-m-d H:i:s')):null],['payment_id']);}}}}
$p->commit();return $result;}catch(Throwable $e){if($p->inTransaction())$p->rollBack();throw $e;}}
